import sys

def main():
    total = int(sys.stdin.readline().strip())
    line = sys.stdin.readline().strip()
    chars = list(line)
    maxRun = 0
    nestedPairs = 0
    i = 0
    while i < total:
        if chars[i] == '(':
            count = 0
            j = i + 1
            while j < total:
                if chars[j] == ')':
                    if count > 0:
                        nestedPairs += 1
                    break
                elif chars[j] == '_':
                    if count > 0:
                        nestedPairs += 1
                        count = 0
                else:
                    count += 1
                j += 1
        elif chars[i] == ')' or chars[i] == '_':
            c = 0
            j = i + 1
            while j < total and chars[j] not in [')', '_', '(']:
                c += 1
                j += 1
            maxRun = max(maxRun, c)
        else:
            c = 0
            j = i
            while j < total and chars[j] not in [')', '_', '(']:
                c += 1
                j += 1
            maxRun = max(maxRun, c)
            i += c - 1
        i += 1
    print(f"{maxRun} {nestedPairs}")

if __name__ == "__main__":
    main()

